  ["2c115ce71a4f8f0d"] = { "Le maniere di Michelle Belle al capezzale sono straordinarie! Forse non può insegnarti quello, ma di sicuro può insegnarti un po' di ⟦First Aid=Primo Soccorso⟧ come si deve. Al momento alloggia alla Lion's Pride Inn.", "." },
  ["2c13ae02d41dec67"] = { "Ascolta bene, perché il signore di ⟦Blackrock=Roccianera⟧ ti distruggerà di certo, se non sarai <pronto/pronta>.", "." },
  ["2c15ccec3228abae"] = { "Avvicinati un po'. Abbiamo questioni importanti da discutere, io e te.\n\nE alcune non vogliamo che le senta chiunque...", "." },
  ["2c1fcac16c1bd6d6"] = { "Aspiranti intrusi, temo.", "." },
  ["2c2ac470e2003289"] = { "Ascolta, {race}. Ascolta bene...\n\nI cavalieri dei draghi arrivarono di notte, in sella allo stormo nero. Colpirono rapidi e con precisione letale, prendendo i cuccioli, come me, e fuggendo sotto il velo dell'oscurità.\n\nGuardai con orrore mentre usavano i miei fratelli e le mie sorelle nei loro esperimenti. Dalla nostra essenza sarebbe stato creato lo stormo cromatico.", "." },
  ["2c2c801a696293fa"] = { "Nessuno può sfidare la Confraternita!", "." },
  ["2c307dd6868e9e89"] = { "Dicono che io abbia ricevuto una benedizione: che sia l'araldo di una nuova era.", "." },
  ["2c329816d8779967"] = { "Questi documenti sono sorvegliati. Parla con Zamek perché crei un diversivo!", "." },
  ["2c3784f1a3be122e"] = { "Pericolo. Pericolo! {name} prova fare male A-Me.", "." },
  ["2c3922bbc70af359"] = { "Salute, {class}. Come posso esserti utile oggi, nel mio umile servizio a Feathermoon Stronghold?", "." },
  ["2c403c18c2cb2465"] = { "Oh oh...", "." },
  ["2c501f082c9e96b8"] = { "Mi prenderò i tuoi soldi e anche la tua vita!", "." },
  ["2c5522e4b7cef8e5"] = { "Sarai un degno sacrificio per Ragnaros.", "." },
  ["2c5d489e2161afc2"] = { "Me ne andai. Non volevo restare con i ⟦Blackrock=Roccianera⟧. No, la morte dei miei figli non sarebbe stata vana. Non avrei servito un maniaco inetto e assetato di potere come Rend.\n\nTrovai rifugio nei boschi di Lordaeron, vivendo da eremita vicino a ⟦Hearthglen=Valsalda⟧.", "." },
  ["2c5ee6bbef95db84"] = { "E ora una rapida occhiata a queste gemme.", "." },
  ["2c63b0a53afadfa3"] = { "<Su questa pergamena è disegnato lo schema di un robot da riparazione da campo.>", "." },
  ["2c6fbd9b13b5ce89"] = { "L'ingresso è nascosto qui a ⟦Moonbrook=Rivoluna⟧. Tieni gli occhi aperti per i ladri. Vogliono la mia morte.", "." },
  ["2c7b5d349d1d60ad"] = { "I simboli sulla tavoletta vengono trascritti con cura...", "." },
